import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';

// An invoice raised on a project. Everything that shows a project's invoices shares the key
// ['invoices', projectId]; invalidating it after a write refreshes the list and its total together.
export type Invoice = { id: number; projectId: number; amount: number; status: string };

export const invoicesKey = (projectId: number) => ['invoices', projectId] as const;

export function useInvoices(projectId: number) {
  return useQuery({
    queryKey: invoicesKey(projectId),
    queryFn: () => getJson<Invoice[]>(`/api/invoices?projectId=${projectId}`),
  });
}

export function useCreateInvoice(projectId: number) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { amount: number }) =>
      postJson<Invoice>('/api/invoices', { projectId, amount: input.amount }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: invoicesKey(projectId) }),
  });
}

// Mark an invoice paid: POSTs {id} and invalidates ['invoices', projectId] so the list reflects the
// new status from the server. The server also keeps an audit record of every payment.
export function usePayInvoice(projectId: number) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { id: number }) =>
      postJson<Invoice>('/api/invoices/pay', { id: input.id }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: invoicesKey(projectId) }),
  });
}

import { formatMoney } from '../../ui/money';
import { useInvoices, usePayInvoice } from './invoices';

// A project's invoices and what they add up to. Reads its own query key (scoped to the project) and
// derives the total from the rows — the aggregate is never stored, so it always matches the list.
// Each row shows its payment status and, while UNPAID, a control to mark it paid.
export function InvoiceList({ projectId }: { projectId: number }) {
  const { data: invoices } = useInvoices(projectId);
  const pay = usePayInvoice(projectId);

  if (!invoices) {
    return null;
  }

  const total = invoices.reduce((sum, invoice) => sum + Number(invoice.amount), 0);

  return (
    <table data-testid="project-invoices-table">
      <thead>
        <tr>
          <th>Amount</th>
          <th>Status</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {invoices.map((invoice) => (
          <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
            <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
            <td data-testid="invoice-status">{invoice.status}</td>
            <td>
              {invoice.status !== 'PAID' && (
                <button
                  type="button"
                  data-testid={`invoice-pay-${invoice.id}`}
                  disabled={pay.isPending}
                  onClick={() => pay.mutate({ id: invoice.id })}
                >
                  Mark paid
                </button>
              )}
            </td>
          </tr>
        ))}
      </tbody>
      <tfoot>
        <tr>
          <td data-testid="project-invoices-total">{formatMoney(total)}</td>
        </tr>
      </tfoot>
    </table>
  );
}

